<?php require_once __DIR__.'/bootstrap.php';$title='Search — AniRead';$q=trim((string)($_GET['q']??''));$page=valid_page();$per=24;$items=[];$total=0;if($q!==''){$like="%$q%";$s=$pdo->prepare('SELECT COUNT(*) FROM anime WHERE title LIKE ? OR english_title LIKE ? OR japanese_title LIKE ?');$s->execute([$like,$like,$like]);$total=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT * FROM anime WHERE title LIKE ? OR english_title LIKE ? OR japanese_title LIKE ? ORDER BY popularity IS NULL,popularity LIMIT ? OFFSET ?');$s->bindValue(1,$like);$s->bindValue(2,$like);$s->bindValue(3,$like);$s->bindValue(4,$per,PDO::PARAM_INT);$s->bindValue(5,($page-1)*$per,PDO::PARAM_INT);$s->execute();$items=$s->fetchAll();}$pages=max(1,(int)ceil($total/$per));include __DIR__.'/includes/header.php';?><h1>Search anime</h1><form class="filters"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search title"><button class="btn">Search</button></form><?php if($q===''):?><p class="muted">Search by title, English title, or Japanese title.</p><?php elseif(!$items):?><p class="muted">No anime matched your search.</p><?php else:?><div class="grid"><?php foreach($items as $a)card($a);?></div><?php page_links($page,$pages,'search.php?q='.rawurlencode($q));endif;include __DIR__.'/includes/footer.php';
